				}

				/// <summary>
				/// The next line, with the terminator the sequence does not carry put back.
				/// </summary>
				private bool Next()
				{
					if (_ended)
						return false;

					if (!_lines.MoveNext())
					{
						_ended = true;

						return false;
					}

					_line = _lines.Current + "\n";
					_at    = 0;

					return true;
				}

				protected override void Dispose(bool disposing)
				{
					if (disposing)
						_lines.Dispose();

					base.Dispose(disposing);
				}
			}

