					".Gram " + action + " state=" + state.ToString() +
					" at " + position.ToString() + " arena=" + arena.ToString());
			}

			/// <summary>
			/// The same line with the rule it happened in and a window of the input around
			/// the position, the caret marking the position itself.
			/// </summary>
