					.Replace("\r", "\\r")
					.Replace("\n", "\\n")
					.Replace("\t", "\\t");

				global::System.Console.Error.WriteLine(
					".Gram " + action + (rule.Length > 0 ? " in " + rule : "") +
					" state=" + state.ToString() + " at " + position.ToString() +
					" \"" + window + "\" arena=" + arena.ToString());
			}
		}
